104: 	b.WriteString("|---|---|---|---|\n")
105: 
106: 	// Sort dossiers by scope
107: 	sorted := make([]AtlasEntry, len(atlas.Dossiers))
108: 	copy(sorted, atlas.Dossiers)
109: 	sort.Slice(sorted, func(i, j int) bool {
110: 		return sorted[i].Scope < sorted[j].Scope
111: 	})
112: 
113: 	for _, d := range sorted {
114: 		b.WriteString(fmt.Sprintf("| %s | %s | %d | %s |\n", d.Scope, d.Kind, d.EntryCount, d.LastUpdated.Format(time.RFC3339)))
115: 	}
116: 	return b.String()
117: }
