27: func TestEntry_RoundTrip(t *testing.T) {
28: 	idx, cleanup := setupTestIndex(t)
29: 	defer cleanup()
30: 
31: 	ctx := context.Background()
32: 	now := time.Now().UTC().Truncate(time.Millisecond)
33: 
34: 	entry := dossiers.Entry{
35: 		ID:           "inv-001",
36: 		Type:         dossiers.EntryTypeInvariant,
37: 		DossierScope: "core/storage",
38: 		Text:         "Storage must always use WAL mode",
39: 		Anchors:      []string{"internal/core/storage/db.go"},
40: 		Source:       ops.SourceHuman,
41: 		Verified:     "verified",
42: 		ClosesWhen:   "",
43: 		CreatedAt:    now,
44: 		UpdatedAt:    now,
45: 	}
46: 
47: 	// 1. UpsertEntry
48: 	if err := idx.UpsertEntry(ctx, entry); err != nil {
49: 		t.Fatalf("UpsertEntry: %v", err)
50: 	}
51: 
52: 	// 2. GetEntry
53: 	got, err := idx.GetEntry(ctx, "inv-001")
54: 	if err != nil {
55: 		t.Fatalf("GetEntry: %v", err)
56: 	}
57: 	if got == nil {
58: 		t.Fatalf("expected non-nil entry")
59: 	}
60: 	if got.ID != entry.ID {
61: 		t.Errorf("expected ID %s, got %s", entry.ID, got.ID)
62: 	}
63: 	if got.Type != entry.Type {
64: 		t.Errorf("expected Type %s, got %s", entry.Type, got.Type)
65: 	}
66: 	if got.DossierScope != entry.DossierScope {
67: 		t.Errorf("expected DossierScope %s, got %s", entry.DossierScope, got.DossierScope)
68: 	}
69: 	if got.Text != entry.Text {
70: 		t.Errorf("expected Text %s, got %s", entry.Text, got.Text)
71: 	}
72: 	if got.Source != entry.Source {
73: 		t.Errorf("expected Source %s, got %s", entry.Source, got.Source)
74: 	}
75: 	if got.Verified != entry.Verified {
76: 		t.Errorf("expected Verified %s, got %s", entry.Verified, got.Verified)
77: 	}
78: 	if len(got.Anchors) != 1 || got.Anchors[0] != "internal/core/storage/db.go" {
79: 		t.Errorf("expected anchors %v, got %v", entry.Anchors, got.Anchors)
80: 	}
81: 
82: 	// 3. Update entry
83: 	entry.Text = "Storage must always use WAL mode and busy timeout"
84: 	entry.UpdatedAt = now.Add(time.Minute)
85: 	if err := idx.UpsertEntry(ctx, entry); err != nil {
86: 		t.Fatalf("UpsertEntry update: %v", err)
87: 	}
88: 
89: 	gotUpdated, err := idx.GetEntry(ctx, "inv-001")
90: 	if err != nil {
91: 		t.Fatalf("GetEntry updated: %v", err)
92: 	}
93: 	if gotUpdated.Text != entry.Text {
94: 		t.Errorf("expected updated text %q, got %q", entry.Text, gotUpdated.Text)
95: 	}
96: 
97: 	// 4. ListEntriesByScope
98: 	byScope, err := idx.ListEntriesByScope(ctx, "core/storage")
99: 	if err != nil {
100: 		t.Fatalf("ListEntriesByScope: %v", err)
101: 	}
102: 	if len(byScope) != 1 || byScope[0].ID != "inv-001" {
103: 		t.Fatalf("expected 1 entry in core/storage, got %v", byScope)
104: 	}
105: 
106: 	emptyScope, err := idx.ListEntriesByScope(ctx, "other/scope")
107: 	if err != nil {
108: 		t.Fatalf("ListEntriesByScope empty: %v", err)
109: 	}
110: 	if len(emptyScope) != 0 {
111: 		t.Errorf("expected 0 entries, got %d", len(emptyScope))
112: 	}
113: 
114: 	// 5. DeleteEntry
115: 	if err := idx.DeleteEntry(ctx, "inv-001"); err != nil {
116: 		t.Fatalf("DeleteEntry: %v", err)
117: 	}
118: 
119: 	_, err = idx.GetEntry(ctx, "inv-001")
120: 	if err == nil {
121: 		t.Fatalf("expected error getting deleted entry, got nil")
122: 	}
123: 	if !errors.Is(err, index.ErrNotFound) {
124: 		t.Errorf("expected ErrNotFound, got %v", err)
125: 	}
126: }
