131: func parseErrorPatternFromEntry(entry dossiers.Entry) (cmdPrefix, pattern string) {
132: 	lines := strings.Split(entry.Text, "\n")
133: 	for _, line := range lines {
134: 		trimmed := strings.TrimSpace(line)
135: 		lower := strings.ToLower(trimmed)
136: 		if strings.HasPrefix(lower, "command:") || strings.HasPrefix(lower, "command_prefix:") || strings.HasPrefix(lower, "cmd:") {
137: 			parts := strings.SplitN(trimmed, ":", 2)
138: 			if len(parts) == 2 {
139: 				cmdPrefix = strings.TrimSpace(parts[1])
140: 			}
141: 		} else if strings.HasPrefix(lower, "pattern:") || strings.HasPrefix(lower, "match:") || strings.HasPrefix(lower, "symptom:") {
142: 			parts := strings.SplitN(trimmed, ":", 2)
143: 			if len(parts) == 2 {
144: 				pattern = strings.TrimSpace(parts[1])
145: 			}
146: 		}
147: 	}
148: 	if pattern == "" && len(lines) > 0 {
149: 		pattern = strings.TrimSpace(lines[0])
150: 	}
151: 	if pattern == "" {
152: 		pattern = entry.ID
153: 	}
154: 	return cmdPrefix, pattern
155: }
