85: func HandlePreToolUse(ctx context.Context, payload []byte, opts ...HookOption) ([]byte, error) {
86: 	if os.Getenv("REPO_MEMORY_DISABLED") == "1" {
87: 		return allowResponse, nil
88: 	}
89: 	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" {
90: 		return allowResponse, nil
91: 	}
92: 
93: 	var input PreToolUsePayload
94: 	if err := json.Unmarshal(payload, &input); err != nil {
95: 		return allowResponse, nil
96: 	}
97: 	input.Normalize()
98: 
99: 	if !isEditTool(input.ToolName) {
100: 		return allowResponse, nil
101: 	}
102: 
103: 	var hookOpts HookOptions
104: 	for _, opt := range opts {
105: 		if opt != nil {
106: 			opt(&hookOpts)
107: 		}
108: 	}
109: 
110: 	workspaceRoot := hookOpts.WorkspaceOverride
111: 	if workspaceRoot == "" {
112: 		if len(input.WorkspacePaths) > 0 {
113: 			workspaceRoot = input.WorkspacePaths[0]
114: 		} else {
115: 			workspaceRoot, _ = os.Getwd()
116: 		}
117: 	}
118: 	if workspaceRoot == "" {
119: 		return allowResponse, nil
120: 	}
121: 
122: 	if !config.IsEnrolledFast(workspaceRoot) {
123: 		return allowResponse, nil
124: 	}
125: 
126: 	dataDir := hookOpts.DataDir
127: 	if dataDir == "" {
128: 		dataDir = config.DataDir()
129: 	}
130: 
131: 	repoID := ""
132: 	if entry, found, _ := config.FindRegistryEntry(dataDir, workspaceRoot); found && entry != nil {
133: 		repoID = entry.RepoID
134: 	}
135: 	if repoID == "" {
136: 		cmd := exec.Command("git", "rev-parse", "--show-toplevel")
137: 		cmd.Dir = workspaceRoot
138: 		out, err := cmd.Output()
139: 		if err == nil {
140: 			repoID = filepath.Base(strings.TrimSpace(string(out)))
141: 		}
142: 	}
143: 	if repoID == "" {
144: 		return allowResponse, nil
145: 	}
146: 
147: 	targetFile := extractTargetFile(input.ToolCall.Args)
148: 	if targetFile == "" {
149: 		return allowResponse, nil
150: 	}
151: 
152: 	idxPath := filepath.Join(dataDir, repoID, "index.db")
153: 	idx, err := index.NewIndex(idxPath)
154: 	if err != nil {
155: 		return allowResponse, nil
156: 	}
157: 	defer idx.Close()
158: 
159: 	engine := delivery.NewEngine(idx, workspaceRoot)
160: 
161: 	// Load the persisted ledger so gate acknowledgments survive across hook invocations.
162: 	ledger, err := LoadLedger(dataDir, repoID, input.ConversationID)
163: 	if err != nil || ledger == nil {
164: 		ledger = delivery.NewLedger(input.ConversationID)
165: 	}
166: 
167: 	targetClean := filepath.Clean(targetFile)
168: 	relPath := targetClean
169: 	if filepath.IsAbs(targetClean) {
170: 		if rel, err := filepath.Rel(workspaceRoot, targetClean); err == nil && !strings.HasPrefix(rel, "..") {
171: 			relPath = rel
172: 		}
173: 	}
174: 
175: 	entries, err := engine.GateEntries(ctx, relPath, ledger)
176: 	if (err != nil || len(entries) == 0) && relPath != targetClean {
177: 		entries, err = engine.GateEntries(ctx, targetClean, ledger)
178: 	}
179: 	if err != nil || len(entries) == 0 {
180: 		return allowResponse, nil
181: 	}
182: 
183: 	// Record the gate entries as pending for this file. PostToolUse will
184: 	// acknowledge them when the edit completes successfully (user approved).
185: 	// Until then, every PreToolUse for this file returns force_ask.
186: 	var gateIDs []string
187: 	for _, ent := range entries {
188: 		gateIDs = append(gateIDs, ent.Entry.ID)
189: 	}
190: 	_ = ModifyLedger(dataDir, repoID, input.ConversationID, func(l *delivery.Ledger) {
191: 		l.SetPendingGates(relPath, gateIDs)
192: 	})
193: 
194: 	reason := delivery.FormatGateDeny(entries[0].Entry)
195: 	resp := PreToolUseResponse{
196: 		Decision: "force_ask",
